//! Configuration of the TLS transport (design/mesh.md section 5.3, ADR 0013): generated by the mesh
//! from the desired state and only read by the TLS transport. It contains no keys: the WebSocket
//! connection is authenticated by the relay probe the mesh sends over it.

use std::fmt;
use std::net::SocketAddr;
use std::str::FromStr;

use serde::{Deserialize, Deserializer, Serialize, Serializer};

/// Message types of relay probes and replies (design/mesh.md section 7.2): the TLS transport
/// uses them to dispatch messages sent back by the relay.
pub const RELAY_PROBE: u8 = 0x90;
pub const RELAY_REPLY: u8 = 0x91;

/// The largest padding a site may choose for the obfuscated transport's sealed messages
/// (design/obfuscation.md section 4: a minimum up to 64 bytes and a maximum up to 256 above it).
pub const MAX_OBFS_PADDING: u16 = 320;

/// The maximum number of TLS relays in one configuration.
pub const MAX_TARGETS: usize = 16;

/// Handed to the transport in memory; it serializes only into the lab's event log, where the keys
/// read as redacted.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct TransportConfig {
    /// Port of this machine's WireGuard: WireGuard messages received from the relay are handed to
    /// this port on the loopback address.
    pub wireguard_port: u16,
    pub targets: Vec<TlsTarget>,
    /// Index of the interface the TLS connections are bound to: on macOS the physical interface
    /// that carries the default route, so a proxy app's tunnel does not carry them (design/
    /// userspace.md section 6.2). Absent where the routing table decides.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub interface: Option<u32>,
    /// Relays reached over the obfuscated UDP transport (design/obfuscation.md section 2).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub obfs: Vec<ObfsTarget>,
}

/// One relay reached over the obfuscated UDP transport.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct ObfsTarget {
    /// Port on this machine's loopback address: WireGuard and the mesh send packets destined for
    /// this relay here.
    pub listen: SocketAddr,
    /// The relay's obfuscated port.
    pub connect: SocketAddr,
    pub key: ObfsKeyBytes,
    pub padding: ObfsPadding,
}

/// A relay's obfuscation key as the transport is handed it. Neither `Debug` nor its serialized form
/// carries it, and it is zeroized when dropped (hard rule 10).
#[derive(Clone, PartialEq, Eq)]
pub struct ObfsKeyBytes(pub [u8; 32]);

impl fmt::Debug for ObfsKeyBytes {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("ObfsKeyBytes(<redacted>)")
    }
}

impl Serialize for ObfsKeyBytes {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.serialize_str("<redacted>")
    }
}

impl Drop for ObfsKeyBytes {
    fn drop(&mut self) {
        zeroize::Zeroize::zeroize(&mut self.0);
    }
}

/// The site's padding range for the obfuscated transport's sealed messages, in bytes.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ObfsPadding {
    pub min: u16,
    pub max: u16,
}

impl ObfsPadding {
    pub fn is_valid(&self) -> bool {
        self.min <= self.max && self.max <= MAX_OBFS_PADDING
    }
}

/// One TLS relay.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct TlsTarget {
    /// Port on this machine's loopback address: WireGuard and the mesh send packets
    /// destined for this relay here.
    pub listen: SocketAddr,
    /// The relay's TLS address. Connects by IP and sends no SNI (design/mesh.md section 5.3).
    pub connect: SocketAddr,
    /// Fingerprint of the relay certificate, against which the client verifies (hard rule 11).
    pub fingerprint: CertFingerprint,
}

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum TransportConfigError {
    #[error("transport config lists {0} targets, more than {MAX_TARGETS}")]
    TooManyTargets(usize),
    #[error("target listens on {0}, which is not a loopback address")]
    NotLoopback(SocketAddr),
    #[error("two targets listen on {0}")]
    DuplicateListen(SocketAddr),
    #[error("wireguard port must not be 0")]
    WireguardPort,
    #[error("obfuscated target {0} has a padding range outside 0-{MAX_OBFS_PADDING}")]
    ObfsPadding(SocketAddr),
}

impl TransportConfig {
    /// Validation at the boundary: local ports are only on the loopback address and are pairwise
    /// distinct.
    pub fn validate(&self) -> Result<(), TransportConfigError> {
        if self.wireguard_port == 0 {
            return Err(TransportConfigError::WireguardPort);
        }
        if self.targets.len() > MAX_TARGETS || self.obfs.len() > MAX_TARGETS {
            return Err(TransportConfigError::TooManyTargets(
                self.targets.len().max(self.obfs.len()),
            ));
        }
        let listens: Vec<SocketAddr> = self
            .targets
            .iter()
            .map(|t| t.listen)
            .chain(self.obfs.iter().map(|t| t.listen))
            .collect();
        for (i, listen) in listens.iter().enumerate() {
            if !listen.ip().is_loopback() {
                return Err(TransportConfigError::NotLoopback(*listen));
            }
            if listens[..i].contains(listen) {
                return Err(TransportConfigError::DuplicateListen(*listen));
            }
        }
        if let Some(t) = self.obfs.iter().find(|t| !t.padding.is_valid()) {
            return Err(TransportConfigError::ObfsPadding(t.connect));
        }
        Ok(())
    }
}

/// SHA-256 of a certificate (leaf certificate DER), whose text form is `sha256:<64 lowercase
/// hexadecimal digits>`.
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub struct CertFingerprint(pub [u8; 32]);

impl fmt::Display for CertFingerprint {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("sha256:")?;
        for b in self.0 {
            write!(f, "{b:02x}")?;
        }
        Ok(())
    }
}

impl fmt::Debug for CertFingerprint {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Display::fmt(self, f)
    }
}

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("certificate fingerprint must be `sha256:` followed by 64 lower-case hex digits")]
pub struct FingerprintError;

impl FromStr for CertFingerprint {
    type Err = FingerprintError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let hex = s.strip_prefix("sha256:").ok_or(FingerprintError)?;
        let bytes = hex.as_bytes();
        if bytes.len() != 64 {
            return Err(FingerprintError);
        }
        let digit = |c: u8| match c {
            b'0'..=b'9' => Ok(c - b'0'),
            b'a'..=b'f' => Ok(c - b'a' + 10),
            _ => Err(FingerprintError),
        };
        let mut out = [0u8; 32];
        for (i, [hi, lo]) in bytes.as_chunks::<2>().0.iter().enumerate() {
            out[i] = digit(*hi)? << 4 | digit(*lo)?;
        }
        Ok(Self(out))
    }
}

impl Serialize for CertFingerprint {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.collect_str(self)
    }
}

impl<'de> Deserialize<'de> for CertFingerprint {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        let s = String::deserialize(d)?;
        s.parse().map_err(serde::de::Error::custom)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fingerprint_round_trips_in_canonical_form_only() {
        let text = format!("sha256:{}", "0a".repeat(32));
        let fp: CertFingerprint = text.parse().expect("parse");
        assert_eq!(fp.0, [0x0a; 32]);
        assert_eq!(fp.to_string(), text);
        for bad in [
            "0a".repeat(32),
            format!("sha256:{}", "0A".repeat(32)),
            format!("sha256:{}", "0a".repeat(31)),
            format!("sha1:{}", "0a".repeat(32)),
        ] {
            assert!(bad.parse::<CertFingerprint>().is_err(), "{bad}");
        }
    }

    #[test]
    fn listen_addresses_stay_on_loopback() {
        let target = |listen: &str| TlsTarget {
            listen: listen.parse().expect("addr"),
            connect: "198.51.100.3:443".parse().expect("addr"),
            fingerprint: CertFingerprint([1; 32]),
        };
        let ok = TransportConfig {
            wireguard_port: 41820,
            targets: vec![target("127.0.0.1:41830"), target("127.0.0.1:41831")],
            interface: None,
            obfs: vec![],
        };
        assert_eq!(ok.validate(), Ok(()));
        let public = TransportConfig {
            targets: vec![target("0.0.0.0:41830")],
            ..ok.clone()
        };
        assert!(matches!(
            public.validate(),
            Err(TransportConfigError::NotLoopback(_))
        ));
        let twice = TransportConfig {
            targets: vec![target("127.0.0.1:41830"), target("127.0.0.1:41830")],
            ..ok
        };
        assert!(matches!(
            twice.validate(),
            Err(TransportConfigError::DuplicateListen(_))
        ));
    }

    /// The interface is written only where there is one, so configurations without it read the
    /// same as before
    #[test]
    fn the_interface_is_written_only_when_there_is_one() {
        let config = TransportConfig {
            wireguard_port: 41820,
            targets: vec![],
            interface: None,
            obfs: vec![],
        };
        let json = serde_json::to_string(&config).expect("json");
        assert_eq!(json, r#"{"wireguard_port":41820,"targets":[]}"#);
        let bound = TransportConfig {
            interface: Some(4),
            ..config
        };
        let json = serde_json::to_string(&bound).expect("json");
        assert!(json.contains(r#""interface":4"#), "{json}");
    }

    /// Written to the lab's event log, a configuration carries no obfuscation key.
    #[test]
    fn a_serialized_configuration_carries_no_key() {
        let config = TransportConfig {
            wireguard_port: 41820,
            targets: vec![],
            interface: None,
            obfs: vec![ObfsTarget {
                listen: "127.0.0.1:41850".parse().expect("addr"),
                connect: "198.51.100.9:30000".parse().expect("addr"),
                key: ObfsKeyBytes([0x5a; 32]),
                padding: ObfsPadding { min: 0, max: 64 },
            }],
        };
        let json = serde_json::to_string(&config).expect("json");
        assert!(json.contains(r#""key":"<redacted>""#), "{json}");
        assert!(!json.contains("90"), "no key byte (0x5a = 90): {json}");
        assert!(!format!("{config:?}").contains("90"), "{config:?}");
    }
}
